"""Disposable real v1 schema fixtures; never migrate a live/user database."""
from __future__ import annotations

import json
import sqlite3
from pathlib import Path

import pytest

from voxarium_studio_remote import migrations as m
from voxarium_studio_remote.protocol import content_hash
from voxarium_studio_remote.store import Store, UnknownLegacySpace, UnknownProject

# The schema copied from the pre-v2 Store, not generated by migration code.
LEGACY_SCHEMA = """
CREATE TABLE IF NOT EXISTS users (
    id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, color TEXT NOT NULL,
    token_hash TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, revoked_at TEXT
);
CREATE TABLE IF NOT EXISTS spaces (
    id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE,
    seq INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS docs (
    space_id TEXT NOT NULL REFERENCES spaces(id), path TEXT NOT NULL,
    content TEXT, hash TEXT, rev INTEGER NOT NULL, deleted INTEGER NOT NULL DEFAULT 0,
    updated_by TEXT, updated_at TEXT NOT NULL, PRIMARY KEY (space_id,path)
);
CREATE INDEX IF NOT EXISTS docs_by_rev ON docs (space_id,rev);
"""
A, B, C = "a" * 32, "b" * 32, "c" * 32
U, V = "1" * 32, "2" * 32
H1, H2 = "3" * 64, "4" * 64


def legacy(path: Path, *, wal: bool = False) -> sqlite3.Connection:
    db = sqlite3.connect(path, isolation_level=None)
    if wal:
        db.execute("PRAGMA journal_mode=WAL")
    db.executescript(LEGACY_SCHEMA)
    db.executemany("INSERT INTO users VALUES (?,?,?,?,?,?)", [
        (U, "Legacy\nName", "#E5484D", H1, "created-user", None),
        (V, "revoked-user", "#3e63dd", H2, "created-user-2", "revoked-stamp"),
    ])
    # B's old name is A's canonical ID: ID lookup must not alias the mapping.
    db.executemany("INSERT INTO spaces VALUES (?,?,?,?)", [
        (A, "old-team", 12, "created-a"), (B, A, 5, "created-b"),
        (C, "empty-team", 0, "created-c"),
    ])
    db.executemany("INSERT INTO docs VALUES (?,?,?,?,?,?,?,?)", [
        (A, "notes/Русский.md", "# Original\r\n🦊", content_hash("# Original\r\n🦊"), 9, 0, U, "updated-9"),
        (A, "gone.txt", None, None, 12, 1, V, "updated-12"),
        (B, "tombstone.md", None, None, 5, 1, U, "updated-5"),
    ])
    return db


def preserved(db):
    return tuple(db.execute("SELECT * FROM docs ORDER BY space_id,path")), tuple(db.execute(
        "SELECT id,name,color,token_hash,created_at,revoked_at FROM users ORDER BY id"))


def test_fresh_bootstrap_and_startup_fail_closed(tmp_path):
    fresh = tmp_path / "fresh.db"
    with_store = Store(fresh)
    assert with_store.list_projects()["projects"] == []
    with_store.close()
    assert m.inspect_database(fresh)["schema_version"] == 2
    path = tmp_path / "legacy.db"
    db = legacy(path)
    db.close()
    original = path.read_bytes()
    with pytest.raises(m.SchemaError, match="explicit offline"):
        Store(path)
    assert path.read_bytes() == original
    assert not path.with_suffix(".db-wal").exists()


def test_full_preservation_mapping_report_and_idempotency(tmp_path):
    path = tmp_path / "legacy.db"
    db = legacy(path)
    before = preserved(db)
    spaces = list(db.execute("SELECT * FROM spaces ORDER BY id"))
    db.close()
    backup = tmp_path / "backup.db"
    original = path.read_bytes()
    plan = m.migrate_database(path, dry_run=True)
    assert plan["changed"] and plan["dry_run"]
    assert path.read_bytes() == original
    assert len(plan["projects"]) == 3
    assert plan["projects"][1]["tombstones"] == 1
    report = m.migrate_database(path, backup_path=backup, confirm_offline=True)
    assert report["schema_version"] == 2 and report["users"] == 2
    assert H1 not in json.dumps(report) and H2 not in json.dumps(report)
    assert "Original" not in json.dumps(report)
    db = sqlite3.connect(path)
    assert preserved(db) == before
    assert list(db.execute("SELECT id,display_name,seq,created_at FROM spaces ORDER BY id")) == spaces
    assert list(db.execute("SELECT id,storage_epoch FROM spaces ORDER BY id")) == [(A, A), (B, B), (C, C)]
    assert list(db.execute("SELECT name,display_name,credential_version,metadata_revision,deleted_at"
                           " FROM users ORDER BY id")) == [
        ("Legacy\nName", "Legacy\nName", 1, 1, None), ("revoked-user", "revoked-user", 1, 1, None)]
    assert db.execute("PRAGMA foreign_key_check").fetchall() == []
    db.close()
    old = sqlite3.connect(backup)
    assert preserved(old) == before and m.schema_version(old) == 1
    old.close()
    again = m.migrate_database(path, confirm_offline=True)
    assert again["changed"] is False
    store = Store(path)
    assert store.project(A).display_name == "old-team"
    assert store.resolve_legacy(A).id == B
    assert store.resolve_legacy("old-team").id == A
    for name in (" old-team", "OLD-TEAM", "unknown"):
        with pytest.raises(UnknownLegacySpace):
            store.resolve_legacy(name)
    with pytest.raises(UnknownProject):
        store.space("old-team")
    assert len(store.list_spaces()) == 3
    store.close()


def test_backup_includes_committed_wal(tmp_path):
    path = tmp_path / "wal.db"
    writer = legacy(path, wal=True)
    assert path.with_suffix(".db-wal").stat().st_size > 0
    report = m.migrate_database(path, backup_path=tmp_path / "backup.db", confirm_offline=True)
    assert report["projects"][0]["seq"] == 12
    backup = sqlite3.connect(tmp_path / "backup.db")
    assert preserved(backup) == preserved(writer)
    backup.close()
    writer.close()


def test_apply_requires_confirmation_and_new_backup(tmp_path):
    path = tmp_path / "old.db"
    legacy(path).close()
    original = path.read_bytes()
    for args in ({}, {"confirm_offline": True}, {"confirm_offline": True, "backup_path": path}):
        with pytest.raises(m.SchemaError):
            m.migrate_database(path, **args)
        assert path.read_bytes() == original
    existing = tmp_path / "backup.db"
    existing.write_bytes(b"precious backup")
    with pytest.raises(FileExistsError):
        m.migrate_database(path, backup_path=existing, confirm_offline=True)
    assert existing.read_bytes() == b"precious backup"
    assert path.read_bytes() == original


@pytest.mark.parametrize("mutation", [
    "PRAGMA user_version=99", "CREATE TABLE surprise (id TEXT)",
    "UPDATE spaces SET id='UPPER' WHERE id='" + C + "'",
    "UPDATE docs SET rev=1000", "UPDATE docs SET hash='broken' WHERE deleted=0",
    "UPDATE docs SET space_id='missing'", "UPDATE docs SET updated_by='missing'",
    "UPDATE docs SET path='../unsafe.md' WHERE deleted=0", "UPDATE docs SET deleted=3",
    "UPDATE users SET token_hash='broken' WHERE id='" + U + "'", "UPDATE spaces SET seq=-1",
])
def test_corrupt_or_unknown_schema_never_repaired(tmp_path, mutation):
    path = tmp_path / "bad.db"
    db = legacy(path)
    db.execute(mutation)
    db.close()
    original = path.read_bytes()
    for args in ({"dry_run": True}, {"confirm_offline": True, "backup_path": tmp_path / "backup.db"}):
        with pytest.raises(m.SchemaError):
            m.migrate_database(path, **args)
        assert path.read_bytes() == original
    with pytest.raises(m.SchemaError):
        Store(path)


def test_failure_rolls_back_schema_and_data(tmp_path, monkeypatch):
    path = tmp_path / "old.db"
    legacy(path).close()
    original = path.read_bytes()
    real = m._upgrade
    calls = 0

    def fail_after_real_upgrade(db):
        nonlocal calls
        calls += 1
        real(db)
        if calls == 2:  # Dry-run succeeds; real transaction must fully roll back.
            raise RuntimeError("injected after rebuild")

    monkeypatch.setattr(m, "_upgrade", fail_after_real_upgrade)
    with pytest.raises(RuntimeError, match="injected"):
        m.migrate_database(path, backup_path=tmp_path / "backup.db", confirm_offline=True)
    assert path.read_bytes() == original
    assert m.inspect_database(path)["schema_version"] == 1
    assert m.inspect_database(tmp_path / "backup.db")["schema_version"] == 1


def test_inspect_missing_or_unknown_database_has_no_bootstrap(tmp_path):
    path = tmp_path / "missing.db"
    with pytest.raises(sqlite3.OperationalError):
        m.inspect_database(path)
    assert not path.exists()
    db = sqlite3.connect(path)
    db.execute("CREATE TABLE unknown (id)")
    db.close()
    original = path.read_bytes()
    with pytest.raises(m.SchemaError):
        Store(path)
    assert path.read_bytes() == original


@pytest.mark.parametrize("mutation", [
    "UPDATE users SET credential_version='NaN'", "UPDATE spaces SET metadata_revision='NaN'",
])
def test_v2_inspection_rejects_noninteger_revisions_without_repair(tmp_path, mutation):
    path = tmp_path / "v2.db"
    db = legacy(path)
    db.close()
    m.migrate_database(path, backup_path=tmp_path / "backup.db", confirm_offline=True)
    db = sqlite3.connect(path)
    db.execute(mutation)
    db.commit()
    db.close()
    original = path.read_bytes()
    with pytest.raises(m.SchemaError):
        m.inspect_database(path)
    with pytest.raises(m.SchemaError):
        m.migrate_database(path, confirm_offline=True)
    assert path.read_bytes() == original
